import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"约翰·穆蒂","description":"","frontmatter":{"title":"约翰·穆蒂","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/约翰·穆蒂.md","filePath":"04_people/约翰·穆蒂.md"}'),o={name:"04_people/约翰·穆蒂.md"};function n(i,a,s,_,d,p){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="约翰·穆蒂" tabindex="-1">约翰·穆蒂 <a class="header-anchor" href="#约翰·穆蒂" aria-label="Permalink to &quot;约翰·穆蒂&quot;">​</a></h1><ul><li><strong>角色职位</strong>：国际乳品皇后（International Dairy Queen）CEO</li><li><strong>与巴菲特关系</strong>：被伯克希尔·哈撒韦收购的子公司 CEO</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>约翰·穆蒂曾担任国际乳品皇后（International Dairy Queen，简称 IDQ）的 CEO。国际乳品皇后是美国著名的冰淇淋和快餐连锁品牌，以&quot;Dairy Queen&quot;（DQ）品牌闻名于世，在全球拥有数千家门店，以其明星产品暴风雪（Blizzard）冰淇淋深受消费者喜爱。</p><p>在穆蒂担任 CEO 期间，国际乳品皇后保持了稳定的增长势头，持续扩大品牌在全球市场的影响力。DQ 的特许经营体系是公司商业模式的核心，穆蒂在此框架下推动了门店标准化运营和产品创新，确保品牌在竞争激烈的餐饮市场中保持吸引力。</p><p>伯克希尔·哈撒韦收购国际乳品皇后是其在消费服务领域的重要布局。巴菲特看中的不仅是 DQ 强大的品牌号召力，更是其稳定的特许经营收入模式和优秀的管理团队。穆蒂作为 CEO，在收购前后的过渡期发挥了关键作用，确保了公司运营的连续性和企业文化的有序传承。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>CEO 任职期</strong>：担任国际乳品皇后 CEO，主导公司日常运营及战略发展方向</li><li><strong>伯克希尔收购</strong>：国际乳品皇后被伯克希尔·哈撒韦收购，成为其餐饮消费板块的核心资产之一</li><li><strong>品牌持续发展</strong>：在伯克希尔控股下，DQ 持续扩张，保持全球冰淇淋连锁品牌的领先地位</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=约翰·穆蒂在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li></ul>',11)])])}const c=e(o,[["render",n]]);export{u as __pageData,c as default};
